import { Flex } from "@chakra-ui/react";
import { InspectorViewHeader } from "../components/InspectorViewHeader";
import { ScrollFadeArea } from "../components/ScrollFadeArea";
import { NoData } from "../Placeholder";
import { PlaceholderImage } from "../types";
import { useInspectorStore } from "../store";
import { selectIsMantleEngine, selectSkillMemory } from "../store/selectors";
import { hasDisplayableSlotData } from "../utils/conversation";
import { deriveSkillMemoryView } from "./deriveSkillMemoryView";
import { SlotsDetails } from "./MemoryDetails";
import { SkillMemoryDetails } from "./SkillMemoryDetails";

interface MemorySectionProps {
  showViewSwitcher?: boolean;
}

export const MemorySection = ({ showViewSwitcher }: MemorySectionProps) => {
  const slotRelatedEvents = useInspectorStore((s) => s.slotRelatedEvents);
  const slots = useInspectorStore((s) => s.slots);
  const isMantleEngine = useInspectorStore(selectIsMantleEngine);
  const skillMemory = useInspectorStore(selectSkillMemory);
  const skillCatalog = useInspectorStore((s) => s.skillCatalog);
  // Base the skill-mode decision on the derived view: entries that were never
  // set are filtered out there, so raw memory keys can be non-empty while the
  // pane has nothing to show.
  const hasSlotData = isMantleEngine
    ? deriveSkillMemoryView(skillMemory ?? {}, skillCatalog, slotRelatedEvents).sections.length > 0
    : hasDisplayableSlotData(slotRelatedEvents, slots);

  return (
    <Flex direction="column" width="100%" height="100%" data-testid="memory-panel">
      <InspectorViewHeader title="Memory" showViewSwitcher={showViewSwitcher} />
      <ScrollFadeArea>
        {hasSlotData ? (
          isMantleEngine ? (
            <SkillMemoryDetails />
          ) : (
            <SlotsDetails />
          )
        ) : (
          <NoData
            image={PlaceholderImage.Cubes}
            shortLabel="Memory"
            longLabel="Memory will be shown here."
          />
        )}
      </ScrollFadeArea>
    </Flex>
  );
};
